// Espejo de la logica de src/CalendarioLaboral.js, src/Factura.js y src/CuentaPorCobrar.js.
// El workflow se exporta autocontenido, por eso las funciones de dominio se copian aqui
// con el mismo algoritmo; los archivos POO son la version independiente y testeable.

function obtenerItems(nombreNodo) {
  try { return $(nombreNodo).all().map(item => item.json); }
  catch (error) { return []; }
}

function aLista(valores) {
  const salida = [];
  for (const valor of valores) {
    if (Array.isArray(valor)) salida.push(...valor);
    else if (Array.isArray(valor?.body)) salida.push(...valor.body);
    else if (Array.isArray(valor?.data)) salida.push(...valor.data);
    else if (valor && typeof valor === 'object') salida.push(valor);
  }
  return salida;
}

function esErrorHTTP(valor) {
  return Boolean(valor && typeof valor === 'object' && (
    valor.error || Number(valor.statusCode) >= 400 ||
    (typeof valor.message === 'string' && !valor.date && !valor.id && !valor.fechaEmision)
  ));
}

function esFechaISO(fecha) {
  if (typeof fecha !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(fecha)) return false;
  const d = new Date(`${fecha}T12:00:00.000Z`);
  return !Number.isNaN(d.getTime()) && d.toISOString().slice(0, 10) === fecha;
}

function hoyCostaRica() {
  const partes = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'America/Costa_Rica', year: 'numeric', month: '2-digit', day: '2-digit'
  }).formatToParts(new Date());
  const p = Object.fromEntries(partes.map(parte => [parte.type, parte.value]));
  return `${p.year}-${p.month}-${p.day}`;
}

function esDiaHabil(fechaISO, feriados) {
  const dia = new Date(`${fechaISO}T12:00:00.000Z`).getUTCDay();
  return dia !== 0 && dia !== 6 && !feriados.has(fechaISO);
}

function sumarDiasHabiles(fechaEmision, cantidad, feriados) {
  const fecha = new Date(`${fechaEmision}T12:00:00.000Z`);
  let contados = 0;
  let intentos = 0;
  while (contados < cantidad) {
    fecha.setUTCDate(fecha.getUTCDate() + 1);
    const actual = fecha.toISOString().slice(0, 10);
    if (esDiaHabil(actual, feriados)) contados += 1;
    intentos += 1;
    if (intentos > 550) throw new Error('Limite de calculo de dias habiles excedido.');
  }
  return fecha.toISOString().slice(0, 10);
}

const fechaActual = hoyCostaRica();
const respuestaFacturasRaw = obtenerItems('Obtener facturas');
const facturas = aLista(respuestaFacturasRaw);

if (facturas.length === 0 || respuestaFacturasRaw.some(esErrorHTTP) || facturas.some(esErrorHTTP)) {
  return [{ json: {
    accion: 'ERROR_JSON_SERVER', id: null,
    motivo: 'No se pudo leer la lista de facturas desde JSON Server o la respuesta esta vacia. No se modifico ningun registro.',
    fechaEvaluacion: fechaActual
  }}];
}

const feriadosActualRaw = obtenerItems('Consultar feriados del ano actual');
const feriadosProximoRaw = obtenerItems('Consultar feriados del proximo ano');
const feriadosActual = aLista(feriadosActualRaw);
const feriadosProximo = aLista(feriadosProximoRaw);
const respuestasFeriadosValidas = [
  { nombre: 'ano actual', raw: feriadosActualRaw, lista: feriadosActual },
  { nombre: 'ano proximo', raw: feriadosProximoRaw, lista: feriadosProximo }
];
const feriadoInvalido = respuestasFeriadosValidas.find(respuesta =>
  respuesta.raw.length === 0 || respuesta.raw.some(esErrorHTTP) ||
  respuesta.lista.length === 0 || !respuesta.lista.every(item => typeof item?.date === 'string' && esFechaISO(item.date))
);

if (feriadoInvalido) {
  return [{ json: {
    accion: 'ERROR_API_FERIADOS', id: null,
    motivo: `La API de feriados no devolvio datos validos para el ${feriadoInvalido.nombre}. Por seguridad no se recalcularon ni actualizaron facturas.`,
    fechaEvaluacion: fechaActual
  }}];
}

const feriados = new Set([...feriadosActual, ...feriadosProximo].map(item => item.date));

function evaluarFactura(factura) {
  if (!factura || typeof factura !== 'object') {
    return { accion: 'ERROR_DATOS', id: null, motivo: 'El registro de factura no es un objeto valido.' };
  }
  if (typeof factura.estado !== 'string' || factura.estado.trim() === '') {
    return { accion: 'ERROR_DATOS', id: factura.id ?? null, motivo: 'estado es obligatorio', noActualizar: true };
  }
  if (factura.estado !== 'pendiente') {
    return { accion: 'IGNORAR', id: factura.id ?? null, motivo: `Estado actual: ${factura.estado}. Solo se procesan facturas pendientes.` };
  }

  const errores = [];
  if (factura.id === undefined || factura.id === null || String(factura.id).trim() === '') errores.push('falta el identificador de factura');
  if (!esFechaISO(factura.fechaEmision)) errores.push('fechaEmision debe tener formato AAAA-MM-DD');
  if (!Number.isInteger(factura.diasHabiles) || factura.diasHabiles < 1 || factura.diasHabiles > 365) errores.push('diasHabiles debe ser un entero entre 1 y 365');
  if (typeof factura.monto !== 'number' || !Number.isFinite(factura.monto) || factura.monto <= 0) errores.push('monto debe ser un numero mayor que cero');
  if (typeof factura.estado !== 'string' || factura.estado.trim() === '') errores.push('estado es obligatorio');
  if (errores.length) {
    return { accion: 'ERROR_DATOS', id: factura.id ?? null, motivo: errores.join('; '), noActualizar: true };
  }

  const fechaVencimiento = sumarDiasHabiles(factura.fechaEmision, factura.diasHabiles, feriados);
  const vencida = fechaActual > fechaVencimiento;
  const estadoCalculado = vencida ? 'vencida' : 'pendiente';
  const diasAtraso = vencida
    ? Math.floor((new Date(`${fechaActual}T12:00:00.000Z`) - new Date(`${fechaVencimiento}T12:00:00.000Z`)) / 86400000)
    : 0;
  const requiereCambio = factura.fechaVencimiento !== fechaVencimiento || factura.estado !== estadoCalculado;

  if (!requiereCambio) {
    return { accion: 'SIN_CAMBIOS', id: factura.id, fechaVencimientoCalculada: fechaVencimiento, estadoCalculado, diasAtraso, motivo: 'La factura ya tiene los datos calculados.' };
  }

  return {
    accion: 'ACTUALIZAR', id: factura.id, fechaVencimientoCalculada: fechaVencimiento,
    estadoCalculado, diasAtraso,
    motivo: vencida ? 'El plazo de pago ya vencio.' : 'Se calculo la fecha de vencimiento.',
    actualizacion: {
      fechaVencimiento, estado: estadoCalculado, diasAtraso, ultimaRevision: fechaActual,
      observacion: vencida ? `Factura vencida; atraso de ${diasAtraso} dia(s).` : 'Factura dentro del plazo de pago.'
    }
  };
}

return facturas.map(factura => ({ json: evaluarFactura(factura) }));
